					fls_data->macpre, fls_data->sec_skew,
					hash_results.md5_digest);
                                tsk_printf("\n");
			}
			else {
	            unsigned char null_buf[16];
				// If the hash calculation had errors, pass in a buffer of nulls
				memset(null_buf, 0, 16);
